CREATE TABLE reviews (id BIGINT NOT NULL AUTO_INCREMENT, rating INT NOT NULL, comment VARCHAR(2000) NOT NULL, created_at TIMESTAMP(6) NOT NULL, user_id BIGINT NOT NULL, trek_id BIGINT NOT NULL, PRIMARY KEY (id), CONSTRAINT uk_reviews_user_trek UNIQUE (user_id, trek_id), CONSTRAINT fk_reviews_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_reviews_trek FOREIGN KEY (trek_id) REFERENCES treks(id));
